### 1. Security Middleware (`middleware/auth.ts`)
```typescript
import { Request, Response, NextFunction } from 'express';
import jwt from 'jsonwebtoken';

export const authenticate = (req: Request, res: Response, next: NextFunction) => {
  const token = req.headers.authorization?.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'Access denied' });

  try {
    const verified = jwt.verify(token, process.env.JWT_SECRET!);
    (req as any).user = verified;
    next();
  } catch {
    res.status(400).json({ error: 'Invalid token' });
  }
};
```

### 2. Global Error Handler (`middleware/errorHandler.ts`)
```typescript
import { Request, Response, NextFunction } from 'express';

export const errorHandler = (err: any, req: Request, res: Response, next: NextFunction) => {
  console.error(err.stack);
  res.status(err.status || 500).json({
    success: false,
    message: err.message || 'Internal Server Error'
  });
};
```

### 3. Core Application (`app.ts`)
```typescript
import express from 'express';
import rateLimit from 'express-rate-limit';
import helmet from 'helmet';
import { authenticate } from './middleware/auth';
import { errorHandler } from './middleware/errorHandler';

const app = express();

// Security & Rate Limiting
app.use(helmet());
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // Limit each IP to 100 requests per window
});
app.use(limiter);
app.use(express.json());

// Routes
app.get('/api/protected', authenticate, (req, res) => {
  res.json({ message: 'Secure data accessed' });
});

// Error handling must be last
app.use(errorHandler);

app.listen(3000, () => console.log('Server running on port 3000'));
```

---

### Key Production Features
*   **Helmet:** Sets secure HTTP headers to prevent common vulnerabilities (XSS, Clickjacking).
*   **Rate Limiting:** Mitigates brute-force attacks and DoS attempts.
*   **JWT Auth:** Stateless authentication; ideal for scalable microservices.
*   **Centralized Error Handling:** Ensures the API never leaks stack traces or raw errors to the client.
*   **Type Safety:** Fully typed Request/Response objects to prevent runtime property errors.

### Implementation Recommendations
1.  **Environment Variables:** Store `JWT_SECRET` and `PORT` in a `.env` file using `dotenv`.
2.  **Validation:** Use **Joi** or **Zod** to validate request bodies before processing.
3.  **Logging:** Integrate **Winston** or **Pino** for structured logging instead of `console.log`.
4.  **Database:** Use an ORM like **Prisma** for type-safe database interactions. 

